/* crosswalk cards, r23. */
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23a"]=[{"q": "p(x) = Σ uₖ(x − w)ᵏ. What is p⁽ᵏ⁾(w)?", "a": "k! uₖ", "w": ["uₖ", "uₖ/k!", "k uₖ"], "why": "Each slope at w picks out one term; (x − w)ᵏ has kth slope k!."}, {"q": "What does the matching polynomial Tₙ agree with at w?", "a": "f and its first n slopes", "w": ["f only", "f at n points", "f and its first slope"], "why": "Matching asks p⁽ᵏ⁾(w) = f⁽ᵏ⁾(w) for k = 0 to n."}, {"q": "What is the coefficient of (x − w)ᵏ in Tₙ?", "a": "f⁽ᵏ⁾(w)/k!", "w": ["f⁽ᵏ⁾(w)", "f⁽ᵏ⁾(x)/k!", "f(w)/k!"], "why": "k! uₖ = f⁽ᵏ⁾(w), so uₖ = f⁽ᵏ⁾(w)/k!."}, {"q": "How many polynomials of degree at most n match f and its first n slopes at w?", "a": "exactly one", "w": ["none", "two", "endlessly many"], "why": "Each coefficient is forced by one slope."}, {"q": "What is T₁ for f at w?", "a": "the tangent line", "w": ["the secant line", "the constant f(w)", "a parabola"], "why": "Same height and same slope at w."}, {"q": "Which powers appear in the matching polynomial of sin at 0?", "a": "odd powers only", "w": ["even powers only", "every power", "powers of 2"], "why": "Its slopes at 0 cycle 0, 1, 0, −1; sin(−x) = −sin x."}, {"q": "T₃ for eˣ at 0?", "a": "1 + x + x²/2 + x³/6", "w": ["1 + x + x² + x³", "x + x²/2 + x³/6", "1 + x + x²/2"], "why": "Every slope of eˣ at 0 is 1; divide by k!."}, {"q": "T₄ for ln(1 + x) at 0?", "a": "x − x²/2 + x³/3 − x⁴/4", "w": ["x − x²/2! + x³/3! − x⁴/4!", "1 + x − x²/2 + x³/3", "x + x²/2 + x³/3 + x⁴/4"], "why": "f⁽ᵏ⁾(0) = (−1)ᵏ⁺¹(k − 1)!, over k! gives ±1/k."}, {"q": "Why is there no T₃ for √x at w = 0?", "a": "√x has no slope at 0", "w": ["√x is not smooth anywhere", "√0 = 0", "the recipe needs w > 1"], "why": "(√h)/h = 1/√h passes every ceiling."}, {"q": "In Tₙ, where are the slopes taken?", "a": "at w, then frozen", "w": ["at x", "halfway between w and x", "at 0 always"], "why": "Tₙ is a polynomial in x; its coefficients are numbers fixed at w."}, {"q": "Accepted name for the matching polynomial?", "a": "the Taylor polynomial", "w": ["the Lagrange polynomial", "the binomial expansion", "the tangent polynomial"], "why": "At 0 it is also called the Maclaurin polynomial."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23b"]=[{"q": "Rₙ(x) = f(x) − Tₙ(x). What does the match-error technique give?", "a": "f⁽ⁿ⁺¹⁾(c)(x − w)ⁿ⁺¹/(n + 1)! for some c between", "w": ["f⁽ⁿ⁺¹⁾(w)(x − w)ⁿ⁺¹/(n + 1)!", "f⁽ⁿ⁾(c)(x − w)ⁿ/n!", "(x − w)ⁿ⁺¹/(n + 1)!"], "why": "The next term left out, with its slope taken at some unknown c."}, {"q": "The match-error technique with n = 0 is which earlier technique?", "a": "the mean value technique", "w": ["the bracket technique", "the chain technique", "level ends, a level point between"], "why": "f(x) − f(w) = f′(c)(x − w)."}, {"q": "|f⁽ⁿ⁺¹⁾| ≤ K between w and x. A ceiling on |Rₙ(x)|?", "a": "K|x − w|ⁿ⁺¹/(n + 1)!", "w": ["K|x − w|ⁿ/n!", "K/(n + 1)!", "K|x − w|"], "why": "The error-ceiling technique: 23b1 with the slope bounded."}, {"q": "For sin and cos, what ceiling K serves every slope?", "a": "1", "w": ["e", "n!", "π"], "why": "Every slope is ±sin or ±cos."}, {"q": "Where does the sum for eˣ reach eˣ?", "a": "at every real x", "w": ["for |x| < 1", "for x ≥ 0 only", "for |x| ≤ e"], "why": "|Rₙ(x)| ≤ e^|x| |x|ⁿ⁺¹/(n + 1)! heads to 0."}, {"q": "ln(1 + x) at x = 2: what does its sum do?", "a": "wanders", "w": ["settles at ln 3", "settles at 0", "settles slowly"], "why": "The pieces 2ᵏ/k grow; smooth alone does not make the error shrink."}, {"q": "For f(x) = x⁴, w = 0, n = 2: which c does the technique give for x = 1?", "a": "¼", "w": ["½", "0", "1"], "why": "R₂(1) = 1 = 24c/6 = 4c."}, {"q": "How many nonzero pieces of the sum for cos give cos 1 to within 10⁻⁶?", "a": "five", "w": ["four", "six", "ten"], "why": "T₈ = T₉, so the error is at most 1/10! < 10⁻⁶; four pieces leave 2.5 × 10⁻⁵."}, {"q": "What does the technique say about where c sits?", "a": "only that it is between w and x", "w": ["it is the midpoint", "it is w", "it is x"], "why": "c exists; for eˣ on [0, 1] with n = 0 it is ln(e − 1) ≈ 0.541."}, {"q": "Accepted name for the match-error technique?", "a": "Taylor's theorem with the Lagrange remainder", "w": ["the mean value theorem", "the ratio test", "Rolle's theorem"], "why": "Rₙ is the remainder."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23c"]=[{"q": "A power sum about w settles at x₀. Where must it settle in size?", "a": "at every x nearer to a than x₀", "w": ["at every x with |x − w| ≤ |x₀ − w|", "only at x₀", "everywhere"], "why": "The reach technique: compare with a geometric sum."}, {"q": "Inside the reach R a power sum…", "a": "settles in size", "w": ["settles only by taking turns", "may wander", "settles at 0"], "why": "The reach-of-a-sum technique."}, {"q": "At |x − w| = R exactly, a power sum…", "a": "may settle or wander", "w": ["always settles", "always wanders", "settles only in size"], "why": "The edges are open: Σ xᵏ, Σ xᵏ/k, Σ xᵏ/k² differ there."}, {"q": "|uₖ₊₁/uₖ| heads to L > 0. The reach?", "a": "1/L", "w": ["L", "L²", "1"], "why": "The ratio test on the pieces: L|x − w| < 1."}, {"q": "Reach of Σ xᵏ/k!?", "a": "no ceiling: it reaches everywhere", "w": ["1", "e", "0"], "why": "The ratio 1/(k + 1) heads to 0."}, {"q": "Reach of Σ k! xᵏ?", "a": "0", "w": ["1", "no ceiling", "½"], "why": "The ratio k + 1 passes every ceiling; it settles only at x = 0."}, {"q": "Reach of Σ 2ᵏxᵏ/k?", "a": "½", "w": ["2", "1", "no ceiling"], "why": "The ratio 2k/(k + 1) heads to 2."}, {"q": "Σ xᵏ/k at x = 1 and x = −1?", "a": "wanders at 1, settles at −1", "w": ["settles at both", "wanders at both", "settles at 1, wanders at −1"], "why": "The harmonic sum at 1; the bracket at −1."}, {"q": "1/(1 + x²) is smooth everywhere. The reach of its sum about 0?", "a": "1", "w": ["no ceiling", "2", "0"], "why": "It is the geometric sum with ratio −x²; the cause lies off the line, at x = i."}, {"q": "The ratio |uₖ₊₁/uₖ| has no limit. Does the sum have a reach?", "a": "yes, always", "w": ["no", "only if it settles at 1", "only if the coefficients are positive"], "why": "The reach comes from the least upper bound; the ratio is one way to find it."}, {"q": "Accepted name for the reach?", "a": "the radius of convergence", "w": ["the interval of convergence", "the ratio", "the domain"], "why": "The stretch with whichever edges settle is the interval of convergence."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23d"]=[{"q": "fₙ settles at each point to f. What may N depend on?", "a": "on ε and on x", "w": ["on ε only", "on x only", "on nothing"], "why": "For every ε and every x there is an N."}, {"q": "fₙ settles everywhere at once to f. What may N depend on?", "a": "on ε only", "w": ["on ε and on x", "on x only", "on n"], "why": "For every ε there is one N that works for every x."}, {"q": "xⁿ on [0, 1] settles at each point to…", "a": "0 below 1, and 1 at 1", "w": ["0 everywhere", "1 everywhere", "x"], "why": "rⁿ → 0 for |r| < 1; 1ⁿ = 1."}, {"q": "Does xⁿ settle everywhere at once on [0, 1]?", "a": "no", "w": ["yes", "only at 1", "only on [0, 1]"], "why": "At x = (½)^(1/n) the gap is ½ for every n."}, {"q": "Does xⁿ settle everywhere at once on [0, 0.9]?", "a": "yes", "w": ["no", "only near 0", "only for n even"], "why": "The worst point is 0.9, and 0.9ⁿ heads to 0."}, {"q": "Continuous fₙ settle everywhere at once to f. Then f is…", "a": "continuous", "w": ["a polynomial", "smooth", "possibly broken"], "why": "The kept-continuity technique, splitting ε in three."}, {"q": "|fₖ(x)| ≤ Mₖ for every x and Σ Mₖ settles. Then Σ fₖ…", "a": "settles everywhere at once", "w": ["settles at each point only", "may wander", "settles in size only at 0"], "why": "The at-once comparison technique: the tail is bounded with no x in it."}, {"q": "Inside its reach, a power sum's total is…", "a": "continuous", "w": ["a polynomial", "broken at the edges", "only defined at w"], "why": "It settles at once on [w − r, w + r], r < R."}, {"q": "x/(1 + nx) on [0, 1]: does it settle everywhere at once?", "a": "yes", "w": ["no", "only at 0", "only at 1"], "why": "Its largest value is 1/(n + 1), at x = 1."}, {"q": "Swap \"for every x there is an N\" to \"there is an N for every x\". The claim…", "a": "gets stronger", "w": ["stays the same", "gets weaker", "becomes false always"], "why": "10a: the order of every and some changes the claim."}, {"q": "Accepted name for settling everywhere at once?", "a": "uniform convergence", "w": ["pointwise convergence", "absolute convergence", "continuity"], "why": "Settling at each point is pointwise convergence."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23e"]=[{"q": "Inside its reach, the slope of Σ uₖ(x − w)ᵏ is…", "a": "Σ k uₖ(x − w)ᵏ⁻¹", "w": ["Σ uₖ(x − w)ᵏ⁻¹", "Σ uₖ(x − w)ᵏ⁺¹/(k + 1)", "not known"], "why": "The term-by-term technique."}, {"q": "A power sum and its slope sum have…", "a": "the same reach", "w": ["the same edges", "reaches that differ by 1", "the same total"], "why": "The same-reach technique; the edges can differ."}, {"q": "Continuous fₙ settle everywhere at once on [p, q]. Their areas…", "a": "head to the area of the limit", "w": ["may head anywhere", "head to 0", "head to 1"], "why": "The area-at-once technique: the gap is at most ε(q − p)."}, {"q": "n²x(1 − x)ⁿ settles at each point to 0 on [0, 1]. Its areas head to…", "a": "1", "w": ["0", "½", "no limit"], "why": "n²/((n + 1)(n + 2)) heads to 1: at each point is not enough."}, {"q": "A power sum about w has total f inside its reach. Then uₖ = …", "a": "f⁽ᵏ⁾(w)/k!", "w": ["f⁽ᵏ⁾(w)", "f(w)/k!", "k! f⁽ᵏ⁾(w)"], "why": "The smooth-sum technique: a power sum is its own matching sum."}, {"q": "Total of Σ k/2ᵏ?", "a": "2", "w": ["1", "4", "no total"], "why": "Σ kxᵏ = x/(1 − x)², at x = ½."}, {"q": "Σ xᵏ/k² settles at x = 1. Its slope sum at 1?", "a": "wanders", "w": ["settles at π²/6", "settles at 1", "settles at ln 2"], "why": "Σ xᵏ⁻¹/k at 1 is the harmonic sum."}, {"q": "arctan x as a power sum about 0, for |x| ≤ 1?", "a": "x − x³/3 + x⁵/5 − ⋯", "w": ["x − x³/3! + x⁵/5! − ⋯", "1 − x² + x⁴ − ⋯", "x + x³/3 + x⁵/5 + ⋯"], "why": "Term by term on 1/(1 + t²) = 1 − t² + t⁴ − ⋯."}, {"q": "1 − ⅓ + ⅕ − ⋯ settles at…", "a": "π/4", "w": ["ln 2", "π/6", "1"], "why": "The arctan sum at x = 1, where arctan 1 = π/4."}, {"q": "Why is x = 1/√3 better than x = 1 for computing π?", "a": "each piece shrinks by a third", "w": ["it settles in size at 1 too", "it needs no leftover bound", "1/√3 is a fraction"], "why": "The leftover bound x²ⁿ⁺¹/(2n + 1) falls fast; 11 pieces give π within 10⁻⁶."}, {"q": "fₙ(x) = sin(nx)/n settles at once to 0. What about fₙ′(0)?", "a": "it is 1 for every n", "w": ["it heads to 0", "it wanders", "it is 0"], "why": "Settling at once carries continuity and areas, not slopes."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23f"]=[{"q": "f(x) = e^(−1/x²), f(0) = 0. As x heads to 0, f(x)/xᵐ…", "a": "heads to 0 for every m", "w": ["heads to 1", "passes every ceiling", "heads to 0 only for m ≤ 2"], "why": "With t = 1/|x|, it is tᵐ/e^(t²); powers lose to exponentials."}, {"q": "Every slope of e^(−1/x²) at 0 is…", "a": "0", "w": ["1", "not defined", "∞"], "why": "The flat-point technique, by induction with Pₙ(1/x)e^(−1/x²)."}, {"q": "The matching sum of e^(−1/x²) at 0 is…", "a": "0, and it reaches everywhere", "w": ["e^(−1/x²)", "1 − 1/x² + ⋯", "undefined"], "why": "Every coefficient is 0."}, {"q": "Where does e^(−1/x²) equal its matching sum at 0?", "a": "only at 0", "w": ["everywhere", "near 0", "for |x| < 1"], "why": "The sum is 0; f(x) > 0 for x ≠ 0."}, {"q": "f is rebuilt from w when…", "a": "some power sum about w with reach above 0 has total f near w", "w": ["f is smooth at w", "f has a slope at w", "f is a polynomial"], "why": "Rebuilt asks the slopes to tell the whole story."}, {"q": "Smooth at w. Does that make f rebuilt from w?", "a": "no", "w": ["yes", "only if a = 0", "only for polynomials"], "why": "e^(−1/x²) at 0 is smooth and not rebuilt."}, {"q": "Two smooth functions share every slope at w. Must they agree near w?", "a": "no", "w": ["yes", "only at two points", "only if both are smooth"], "why": "Add e^(−1/(x − w)²) to one of them."}, {"q": "A smooth g: 0 for x ≤ 0 and positive for x > 0?", "a": "e^(−1/x²) for x > 0, 0 otherwise", "w": ["x for x > 0, 0 otherwise", "x² for x > 0, 0 otherwise", "|x|"], "why": "Every slope at 0 is 0 from both sides."}, {"q": "f(0.2) = e⁻²⁵ compared with 0.2¹⁰ ≈ 1.0 × 10⁻⁷?", "a": "far smaller: about 1.4 × 10⁻¹¹", "w": ["far larger", "about equal", "exactly equal"], "why": "Flatter than any power near 0."}, {"q": "Accepted name for a function rebuilt from w?", "a": "analytic at w", "w": ["smooth at w", "continuous at w", "infinitely differentiable at w"], "why": "e^(−1/x²) is smooth but not analytic at 0."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23g"]=[{"q": "If e = p/q, the proof builds x = q!(e − Σₖ≤q 1/k!). What kind of number is x?", "a": "a whole number", "w": ["a fraction with bottom q", "a negative number", "irrational"], "why": "q!/q and each q!/k! with k ≤ q are whole."}, {"q": "Where does the proof for e trap x?", "a": "strictly between 0 and 1", "w": ["between 1 and 2", "at 0", "between 0 and q"], "why": "x > 0, and x < 1/(q + 1) + 1/(q + 1)² + ⋯ = 1/q ≤ 1."}, {"q": "If e were 8/3, what would x be?", "a": "0", "w": ["1", "⅓", "0.3097"], "why": "8/3 = 1 + 1 + ½ + ⅙; the line x > 0 fails."}, {"q": "In the proof for π, which quantity must be whole?", "a": "the area ∫₀^π f(x) sin x dx", "w": ["π itself", "f(π)", "the slope f′(0)"], "why": "It equals F(π) + F(0), and every slope of f at 0 and π is whole."}, {"q": "Why must n be large in the proof for π?", "a": "so that π(πp)ⁿ/n! falls below 1", "w": ["so that f has whole slopes", "so that F″ + F = f", "so that sin is positive"], "why": "xⁿ/n! heads to 0; with p = 22 it needs n = 186."}, {"q": "Is 2.718281828 equal to e?", "a": "no: it is a fraction, and e is not", "w": ["yes, to nine places", "yes", "only if rounded"], "why": "e − 2.718281828 ≈ 4.6 × 10⁻¹⁰."}, {"q": "A real is algebraic when…", "a": "it is a root of a nonzero polynomial with whole coefficients", "w": ["it is a fraction", "it has a repeating decimal", "it can be computed"], "why": "√2 is algebraic, a root of x² − 2."}, {"q": "A polynomial with whole coefficients that has √2 + √3 as a root?", "a": "x⁴ − 10x² + 1", "w": ["x² − 5", "x⁴ − 5x² + 6", "x² − 2x − 1"], "why": "x² = 5 + 2√6; square x² − 5 = 2√6."}, {"q": "e and π are not fractions. Is e + π?", "a": "nobody knows", "w": ["no, never", "yes", "it is 5.86, a fraction"], "why": "√2 and −√2 are not fractions, yet their sum is 0."}, {"q": "Why can no ruler-and-compass recipe square the circle?", "a": "π is transcendental, so √π cannot be built", "w": ["π is irrational", "circles have no corners", "√π is negative"], "why": "Ruler and compass build only algebraic lengths; the claim on π is held in trust."}, {"q": "Accepted name for a real that is not algebraic?", "a": "transcendental", "w": ["irrational", "imaginary", "rational"], "why": "e and π are transcendental."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23h"]=[{"q": "What is the sum of eˣ about 2?", "a": "Σ e²(x − 2)ᵏ/k!, reaching everywhere", "w": ["Σ 2ᵏxᵏ/k!", "Σ (x − 2)ᵏ/k!", "e² + Σ xᵏ/k!"], "why": "The recentring technique: eˣ = e²·e^(x − 2), and the sum for eʰ reaches everywhere."}, {"q": "How far does the sum for ln x about w reach?", "a": "w: it holds for 0 < x ≤ 2w", "w": ["1", "everywhere", "2w"], "why": "ln x = ln w + ln(1 + h/w), and the sum for ln(1 + u) needs −1 < u ≤ 1."}, {"q": "What is (α choose k) for any real α?", "a": "α(α − 1)⋯(α − k + 1)/k!", "w": ["αᵏ/k!", "α!/(k!(α − k)!) only", "k(k − 1)⋯(k − α + 1)/α!"], "why": "It is the kth slope of (1 + x)^α at 0, over k!."}, {"q": "For which x does (1 + x)^α = Σ (α choose k)xᵏ, when α is not a whole number?", "a": "|x| < 1, at least", "w": ["every x", "x > −1", "|x| ≤ 2"], "why": "The ratio of neighbouring coefficients heads to 1, so the reach is 1."}, {"q": "How does 23h prove the binomial sum reaches (1 + x)^α?", "a": "S(x)/(1 + x)^α has slope 0, so it is flat at 1", "w": ["by bounding every slope of (1 + x)^α", "by squaring the sum", "by checking many x"], "why": "Term by term, (1 + x)S′ = aS, so the quotient's slope is 0 (14d)."}, {"q": "What are the first terms of √(1 + x)?", "a": "1 + x/2 − x²/8 + x³/16 − ⋯", "w": ["1 + x/2 + x²/8 + x³/16 + ⋯", "1 − x/2 + 3x²/8 − ⋯", "1 + x/2 − x²/4 + ⋯"], "why": "(½ choose 2) = (½)(−½)/2 = −1/8; (½ choose 3) = 1/16."}, {"q": "Why is a sum built from old sums the right one?", "a": "a function has only one power sum about a point", "w": ["because it was checked at many points", "because every smooth function equals its sum", "because the pieces head to 0"], "why": "The smooth-sum technique (23e3): the coefficients are f⁽ⁿ⁾(w)/n!."}, {"q": "The piece with x⁶ in the sum for e^(x²) is x⁶/3!. What is the sixth slope at 0?", "a": "120", "w": ["1/6", "720", "6"], "why": "f⁽⁶⁾(0)/6! = 1/3!, so f⁽⁶⁾(0) = 720/6."}, {"q": "In the product of Σ uₖxᵏ and Σ vₖxᵏ, what is the coefficient of xᵏ?", "a": "u₀vₖ + u₁vₖ₋₁ + ⋯ + uₖv₀", "w": ["uₖvₖ", "(u₀ + ⋯ + uₖ)(v₀ + ⋯ + vₖ)", "uₖ + vₖ"], "why": "Gather every pair of powers that adds to k (the product technique)."}, {"q": "Which sum for ln 2 gains about one place per piece?", "a": "2(⅓ + 1/(3·3³) + 1/(5·3⁵) + ⋯)", "w": ["1 − ½ + ⅓ − ¼ + ⋯", "1 − ½ + ⅓ − ¼ + ⋯, taken in pairs", "Σ (−1)ᵏ/k!"], "why": "ln((1 + x)/(1 − x)) at x = ⅓: each piece is under a ninth of the last."}, {"q": "Is √4 = 1 + 3/2 − 9/8 + 27/16 − ⋯?", "a": "No: x = 3 is outside the reach, and the sum wanders", "w": ["Yes, slowly", "Yes, if the pieces are taken in pairs", "No: it settles at −2"], "why": "The binomial sum reaches only |x| < 1 when a is not whole."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23i"]=[{"q": "The signs take turns and the sizes fall. What fences the leftover?", "a": "the next piece, in size", "w": ["the next piece over 1 − k", "the error ceiling only", "the sum of the next two pieces"], "why": "The bracket (22g1)."}, {"q": "Each piece is at most k times the last, k < 1, all positive. What fences the leftover?", "a": "the next piece over 1 − k", "w": ["the next piece", "k times the last piece", "1/(1 − k)"], "why": "A geometric sum laid over the tail (22i2)."}, {"q": "When is a total known to six places?", "a": "when every number in its fence, slips included, rounds to the same six places", "w": ["when the fence is narrower than 0.0000005", "when the next piece is below 0.0000005", "when six pieces have been added"], "why": "The rounding-fence technique: a narrow fence can still straddle a rounding boundary."}, {"q": "How many pieces of Σ 1/k! give e to six places?", "a": "ten, through 1/9!", "w": ["six", "seven", "twenty"], "why": "Ten pieces fence e in [2.718281522, 2.718281836], which rounds to 2.718282."}, {"q": "How many pieces of the sum for sin give sin 0.1 to six places?", "a": "two", "w": ["one", "three", "six"], "why": "0.1 − 0.001/6 = 0.0998333, and the leftover is below 0.1⁵/120 < 10⁻⁷."}, {"q": "For |θ| ≤ h in radians, how close is sin θ to θ?", "a": "within h³/6", "w": ["within h²/2", "within h²/6", "within h/6"], "why": "sin has no θ² piece, so the match of degree 1 is the match of degree 2; the error is R₂."}, {"q": "For |θ| ≤ h in radians, how close is cos θ to 1 − θ²/2?", "a": "within h⁴/24", "w": ["within h³/6", "within h²/2", "within h⁴/4"], "why": "cos has no θ³ piece; the fourth slope is cos, at most 1."}, {"q": "Is sin 1° about 1?", "a": "No: 1° is π/180 rad, and sin 1° ≈ 0.01745", "w": ["Yes, 1° is a small angle", "Yes, to two places", "No: sin 1° ≈ 0.8415"], "why": "The small-angle technique needs radians."}, {"q": "How does a calculator find sin 10?", "a": "takes off three half turns, then sums at 0.575", "w": ["sums the series at x = 10", "uses sin 10 ≈ 10", "looks it up in a table of every value"], "why": "The bring-near technique: sin(3π + x) = −sin x, exactly; the sum then shrinks fast."}, {"q": "The sum for sin settles at x = 100. Why not add it there?", "a": "its pieces climb past 10⁴², so rounding slips swamp the answer", "w": ["it settles at the wrong total", "it needs a million pieces", "sin 100 is not defined"], "why": "Settling is about exact arithmetic; a calculator keeps only so many figures."}, {"q": "How many pieces of 1 − ½ + ⅓ − ⋯ promise ln 2 to six places?", "a": "about two million", "w": ["about twenty", "about two thousand", "six"], "why": "The bracket fence is 1/(n + 1), which must be below 0.0000005."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23j"]=[{"q": "A(x) = u₀ + u₁x + u₂x² + ⋯ for a list u₀, u₁, u₂, …. What is A called?", "a": "the storing function of the list", "w": ["the matching polynomial of the list", "the reach of the list", "the running total of the list"], "why": "Each number of the list sits in front of its power."}, {"q": "1, 1, 1, 1, …. Which is its storing function?", "a": "1/(1 − x)", "w": ["1/(1 + x)", "x/(1 − x)", "1/(1 − x)²"], "why": "The geometric sum Σ xᵏ, for |x| < 1."}, {"q": "1/(1 − x)². Which list does it store?", "a": "1, 2, 3, 4, …", "w": ["1, 1, 1, 1, …", "1, 4, 9, 16, …", "1, 2, 4, 8, …"], "why": "The slope of 1/(1 − x), term by term, gives Σ (k + 1)xᵏ."}, {"q": "A list's storing function is A(x). Which list does x·A(x) store?", "a": "the same list, moved one place on, with 0 first", "w": ["the list with every number doubled", "the list moved one place back", "the list of running totals"], "why": "Times x raises every power by one."}, {"q": "Two storing functions with reach above 0 agree for every x near 0. What follows?", "a": "the two lists are the same", "w": ["only their first numbers agree", "the lists agree from some place on", "nothing, without more slopes"], "why": "Read-back: uₖ = A⁽ᵏ⁾(0)/k!, and the slopes at 0 agree."}, {"q": "A line reads G(x)(1 − x − x²) = x for the rabbit counts. What made every bracket after the first two 0?", "a": "the technique Fₖ = Fₖ₋₁ + Fₖ₋₂", "w": ["the reach of G", "partial fractions", "the starting values 0 and 1"], "why": "Each bracket is Fₖ − Fₖ₋₁ − Fₖ₋₂."}, {"q": "Fₙ = (φⁿ − ψⁿ)/√5. What is it called on the page?", "a": "the rabbit closed form", "w": ["the read-back technique", "the product technique", "the matching polynomial"], "why": "It gives any rabbit count at once, with no technique run."}, {"q": "x/(1 − x − x²) at x = 1 gives −1. Is 0 + 1 + 1 + 2 + 3 + ⋯ equal to −1?", "a": "no: 1 is outside the reach", "w": ["yes: the formula holds everywhere", "yes, by read-back", "no: the formula has a slip"], "why": "The reach is 1/φ ≈ 0.618; at 1 the sum wanders."}, {"q": "In A(x)B(x), what stands in front of xⁿ?", "a": "u₀vₙ + u₁vₙ₋₁ + ⋯ + uₙv₀", "w": ["uₙvₙ", "uₙ + vₙ", "(u₀ + ⋯ + uₙ)(v₀ + ⋯ + vₙ)"], "why": "Every split of n into a part from A and a part from B."}, {"q": "Ways to make n cents from pennies, nickels and dimes. Which storing function counts them?", "a": "1/((1 − x)(1 − x⁵)(1 − x¹⁰))", "w": ["(1 + x)(1 + x⁵)(1 + x¹⁰)", "1/(1 − x − x⁵ − x¹⁰)", "1/(1 − x)¹⁶"], "why": "One geometric sum per coin, multiplied."}, {"q": "(1 + x)ᵐ(1 + x)ⁿ = (1 + x)ᵐ⁺ⁿ, read at xʳ. What does it count?", "a": "choices of r from m + n, split by how many come from the m", "w": ["arrangements of r things", "choices of r from m, times choices from n", "ways to total r with two dice"], "why": "The product technique on the choose numbers."}, {"q": "Fₙ is the whole number nearest φⁿ/√5. Why?", "a": "ψⁿ/√5 is under ½ in size", "w": ["φⁿ/√5 is whole", "ψⁿ is 0", "√5 is close to 2"], "why": "Fₙ = φⁿ/√5 − ψⁿ/√5 and |ψ| < 1."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23k"]=[{"q": "|f(x) − Σ_{k<n} (−1)ᵏk!xᵏ| ≤ n!xⁿ, yet Σ (−1)ᵏk!xᵏ settles only at 0. What is the sum to f?", "a": "an expansion of f as x shrinks", "w": ["the matching sum of f, settling to f", "a storing function of f", "a power sum with reach 1"], "why": "Fixed pieces, shrinking x: the error shrinks like the next power."}, {"q": "An expansion's pieces at x = 0.1 shrink until k = 9 and then grow. Where do you stop?", "a": "just before the smallest piece", "w": ["after as many pieces as you can", "after the first piece", "where the pieces first grow past 1"], "why": "Cut-at-the-smallest: the error is at most that piece."}, {"q": "A sum settles at x. What does that promise?", "a": "fix x, take more pieces, and the error heads to 0", "w": ["fix the pieces, shrink x, and the error shrinks", "the error is at most the next piece", "the pieces shrink, then grow"], "why": "Settling is the other promise from an expansion as x shrinks."}, {"q": "∫₀^∞ tᵏe^(−t) dt. What is it?", "a": "k!", "w": ["kᵏ", "eᵏ", "1/k!"], "why": "Parts gives k times the area for k − 1, and the area for 0 is 1."}, {"q": "ln g has its top at m and (ln g)″ ≥ −K beside it. What bound on g follows there?", "a": "g(t) ≥ e^(−K(t − m)²/2)·g(m)", "w": ["g(t) ≤ e^(−K(t − m)²/2)·g(m)", "g(t) ≥ g(m) − K(t − m)", "g(t) = g(m) near m"], "why": "The match-error technique with n = 1, the slope 0 at the top."}, {"q": "tⁿe^(−t). Where is its top, and what is its height there?", "a": "at t = n, height (n/e)ⁿ", "w": ["at t = 1, height e^(−1)", "at t = n, height n!", "at t = e, height eⁿ"], "why": "(ln g)′ = n/t − 1 is 0 at t = n."}, {"q": "dₙ = ln n! − (n + ½) ln n + n. What does the trapezoid fence say?", "a": "dₙ falls to some c, with c < dₙ < c + 1/(8n)", "w": ["dₙ climbs to 1", "dₙ = ln √(2π) for every n", "dₙ wanders"], "why": "The slivers between ln and its chords add to at most ⅛."}, {"q": "Why is the chord of ln on [k, k + 1] under the curve?", "a": "ln Bends Down", "w": ["ln climbs", "ln is positive there", "the strip is one unit wide"], "why": "A curve that bends down lies above its chords."}, {"q": "Iₘ = ∫₀^(π/2) sinᵐx dx. Which line is right?", "a": "Iₘ = ((m − 1)/m)·Iₘ₋₂", "w": ["Iₘ = (m/(m − 1))·Iₘ₋₂", "Iₘ = Iₘ₋₁ − Iₘ₋₂", "Iₘ = m·Iₘ₋₁"], "why": "Parts on sinᵐ⁻¹x·sin x, with cos² = 1 − sin²."}, {"q": "n! ~ √(2πn)(n/e)ⁿ. What is it called?", "a": "the size-of-factorials technique (Stirling's formula)", "w": ["the factorial fence", "the peak technique", "the trapezoid-fence technique"], "why": "The constant √(2π) comes from areas under powers of sin."}, {"q": "n! ~ √(2πn)(n/e)ⁿ. Does n! − √(2πn)(n/e)ⁿ head to 0?", "a": "no: only the ratio heads to 1", "w": ["yes, like 1/(12n)", "yes, by the trapezoid fence", "only for even n"], "why": "At n = 10 the gap is 30 104, and it passes every ceiling."}, {"q": "(2ᵏk!)⁴/(((2k)!)²(2k + 1)) heads to π/2. Does it equal π/2 for some large k?", "a": "no: each value is a fraction", "w": ["yes, once k passes 100", "yes, at k = 1", "only in the limit's last term"], "why": "π is not a fraction (23g)."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["23l"]=[{"q": "h(½f₀ + f₁ + ⋯ + f_{N−1} + ½f_N). What is it?", "a": "the trapezoid sum", "w": ["the parabola sum", "a lower sum", "the best-points technique"], "why": "Chords on every strip, each trapezoid h times its average height."}, {"q": "(h/3)(f₀ + 4f₁ + 2f₂ + 4f₃ + ⋯ + f_N). What is it?", "a": "the parabola sum", "w": ["the trapezoid sum", "an upper sum", "the best-points technique"], "why": "Weights 1, 4, 1 on each pair of strips."}, {"q": "|f″| ≤ K on [u, v]. Which bound does the trapezoid technique give?", "a": "(v − u)Kh²/6", "w": ["(v − u)Kh⁴/45", "(v − u)Kh/2", "Kh³/6 for the whole area"], "why": "Kh³/6 per strip, N = (v − u)/h strips."}, {"q": "The strip width is halved. What happens to the trapezoid error bound?", "a": "it falls to a quarter", "w": ["it halves", "it falls to a sixteenth", "it does not change"], "why": "The bound shrinks like h²."}, {"q": "The strip width is halved. What happens to the parabola error bound?", "a": "it falls to a sixteenth", "w": ["it falls to a quarter", "it halves", "it falls to an eighth"], "why": "The bound shrinks like h⁴."}, {"q": "Which polynomials does the parabola technique give exactly, on a pair of strips?", "a": "every polynomial of degree 3 or less", "w": ["degree 2 or less only", "every polynomial", "degree 1 or less only"], "why": "Exact for 1 and t², and for t and t³ by symmetry."}, {"q": "What does the trapezoid technique's proof match the curve with, on each strip?", "a": "its matching polynomial of degree 1 about the middle", "w": ["its chord", "its matching polynomial of degree 3", "a parabola through three heights"], "why": "The line parts cancel; the error ceiling bounds what is left."}, {"q": "f(−1/√3) + f(1/√3), as a technique for ∫ over [−1, 1]. What is it exact for?", "a": "every cubic", "w": ["every polynomial of degree 2 or less only", "every polynomial of degree 4", "lines only"], "why": "The best-points technique: two heights, exact to degree 3."}, {"q": "Can any technique with n heights be exact for every polynomial of degree 2n?", "a": "no", "w": ["yes, with the best points", "yes, with weights 1, 4, 1", "only for n = 1"], "why": "(t − x₁)²⋯(t − xₙ)² has area above 0 and technique value 0."}, {"q": "(4T_{h/2} − T_h)/3. What is it?", "a": "the parabola sum S_{h/2}", "w": ["the trapezoid sum T_{h/4}", "the exact area", "the best-points technique"], "why": "The blend cancels the h² part of the trapezoid error."}, {"q": "The trapezoid technique on √x over [0, 1]. Does the h² bound apply?", "a": "no: f″ has no ceiling near 0", "w": ["yes, with K = ¼", "yes, since √x is continuous", "no: √x has no area"], "why": "f″ = −¼x^(−3/2) passes every ceiling near 0."}, {"q": "The trapezoid technique with N = 1 on [−1, 1]. Is it the best-points technique?", "a": "no: its heights at ±1 are exact only for lines", "w": ["yes: two heights, weight 1 each", "yes, for even functions", "no: it uses three heights"], "why": "The best points are ±1/√3."}];
