(function(C){C["23a"]=(C["23a"]||[]).concat([{"q": "Has √x a match T₃ at w = 0?", "a": "no: √x has no slope at 0, so there is nothing to match", "w": ["yes: T₃ = 0", "yes: T₃ = x/2", "no: √x is not continuous at 0"], "why": "The match technique asks for n slopes at w."}, {"q": "f and Tₙ agree at w. Is it thereby shown that they agree near w?", "a": "no: the match fixes the value and n slopes at w only", "w": ["yes, wherever f is smooth", "yes, on some interval round w", "yes, as far as the first place where f is 0"], "why": "How near they stay away from w is the question of the error."}, {"q": "Which number stands in front of (x − w)ᵏ in the match?", "a": "f⁽ᵏ⁾(w)/k!", "w": ["f⁽ᵏ⁾(w)/k", "k! · f⁽ᵏ⁾(w)", "f⁽ᵏ⁾(w)"], "why": "The k-th slope of uₖ(x − w)ᵏ at w is k!·uₖ, and matching asks that to be f⁽ᵏ⁾(w)."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23b"]=(C["23b"]||[]).concat([{"q": "For which x does the error ceiling show that the matches of sin head to sin x?", "a": "for every x: every slope is ±sin or ±cos, so K = 1", "w": ["only for |x| < 1", "only for |x| ≤ π", "only for x = 0"], "why": "|Rₙ(x)| ≤ |x|ⁿ⁺¹/(n + 1)!, and that heads to 0 for any x."}, {"q": "Is |Rₙ(x)| ≤ |x − w|ⁿ⁺¹/(n + 1)! for every f?", "a": "no: only with the ceiling K = 1 on the slope; eˣ needs e^|x|", "w": ["yes, by the error-ceiling technique", "no: it holds for no f", "yes, if f is smooth"], "why": "Error-ceiling technique: |Rₙ(x)| ≤ K|x − w|ⁿ⁺¹/(n + 1)!, where K is a ceiling on |f⁽ⁿ⁺¹⁾| between w and x."}, {"q": "In the match-error technique, where is the slope f⁽ⁿ⁺¹⁾ taken?", "a": "at some c between w and x", "w": ["at the midpoint of w and x", "at w", "at x"], "why": "Rₙ(x) = f⁽ⁿ⁺¹⁾(c)(x − w)ⁿ⁺¹/(n + 1)! for some c between w and x. The technique does not say where c is."}, {"q": "What is Rₙ(x)?", "a": "f(x) − Tₙ(x), what the match leaves over", "w": ["Tₙ₊₁(x) − Tₙ(x), the next piece", "f⁽ⁿ⁾(x), the n-th slope", "f(x) − f(w)"], "why": "The error is the next piece with its slope taken somewhere between, not the next piece itself."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23c"]=(C["23c"]||[]).concat([{"q": "What is a power sum about w?", "a": "Σ uₖ(x − w)ᵏ, with real numbers uₖ in front", "w": ["any endless sum of functions", "Σ uₖ · kˣ", "a polynomial in x − w"], "why": "Accepted name: a power series. For each x it is an endless sum of reals, which settles or wanders."}, {"q": "f is smooth everywhere. Must its power sum about 0 reach everywhere?", "a": "no: 1/(1 + x²) is smooth along the whole line, and its sum about 0 has the reach 1", "w": ["yes: a smooth function has no edge", "no: no power sum reaches everywhere", "yes, by the reach-of-a-sum technique"], "why": "Its sum is the geometric sum with ratio −x², which wanders once |x| ≥ 1."}, {"q": "|uₖ₊₁/uₖ| heads to L > 0. What is the reach of Σ uₖ(x − w)ᵏ?", "a": "1/L", "w": ["L", "1 − L", "L²"], "why": "Reach-by-ratio technique: the ratio of neighbouring pieces heads to L|x − w|, and the ratio test asks that to be under 1."}, {"q": "A power sum about 0 settles at x₀. Must it settle at −x₀?", "a": "no: only at every x nearer to 0 than x₀; Σ xᵏ/k settles at −1 and wanders at 1", "w": ["yes: x₀ and −x₀ are as far from 0", "yes, by the reach technique", "no: it then wanders at every x < 0"], "why": "Reach technique: it settles in size at every x nearer to the centre than x₀ is. The other edge is as far, not nearer."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23d"]=(C["23d"]||[]).concat([{"q": "What changes between settling at each point and settling everywhere at once?", "a": "only the order: one N for each ε that works for every x, in place of an N that may depend on x", "w": ["the challenge: ε may now depend on x", "the limit function f", "nothing: they are two names for one thing"], "why": "At each point: for every ε and every x there is an N. Everywhere at once: for every ε there is one N for every x."}, {"q": "Each fₙ is continuous, and fₙ settles at each point to f. Must f be continuous?", "a": "no: xⁿ on [0, 1] settles at each point to a function that jumps at 1", "w": ["no: such an f is never continuous", "yes, by the kept-continuity technique", "yes: a limit of continuous functions is continuous"], "why": "The kept-continuity technique asks for settling everywhere at once."}, {"q": "xⁿ settles everywhere at once on [0, r] for each r < 1. Does it settle everywhere at once on [0, 1)?", "a": "no: for each n some x under 1 still has xⁿ ≥ ½", "w": ["yes: take the largest of the N for each r", "yes: [0, 1) is made of the stretches [0, r]", "no: it does not settle at each point of [0, 1)"], "why": "Each r has its own N, and those N have no ceiling as r nears 1. One N for the whole of [0, 1) does not exist."}, {"q": "|fₖ(x)| ≤ Mₖ for every x in D and every k, and Σ Mₖ settles. What follows?", "a": "Σ fₖ settles everywhere at once on D", "w": ["each fₖ is continuous on D", "Σ fₖ settles at each point of D, and no more is shown", "Σ fₖ = Σ Mₖ on D"], "why": "At-once comparison technique: the tail is bounded by the tail of Σ Mₖ, with no x left in it."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23e"]=(C["23e"]||[]).concat([{"q": "fₙ settles at each point to f on [0, 1]. Must ∫₀¹ fₙ head to ∫₀¹ f?", "a": "no: n²x(1 − x)ⁿ has areas heading to 1, and its limit has area 0", "w": ["yes, by the area-at-once technique", "no: the areas never settle", "yes, if each fₙ is continuous"], "why": "The area-at-once technique asks for settling everywhere at once."}, {"q": "Is (Σ fₖ)′ = Σ fₖ′ for any functions fₖ?", "a": "no: it is proved for power sums, inside the reach", "w": ["yes, wherever Σ fₖ settles", "yes: the slope of a sum is the sum of the slopes", "no: not even for power sums"], "why": "For finitely many functions the slope of a sum is the sum of the slopes. For endlessly many it needs a proof, and the term-by-term technique gives one for power sums."}, {"q": "Inside its reach, f(x) = Σ uₖ(x − w)ᵏ. What is uₖ?", "a": "f⁽ᵏ⁾(w)/k!", "w": ["it cannot be told from f", "f(w + k)", "f⁽ᵏ⁾(w)"], "why": "Smooth-sum technique: a power sum is smooth inside its reach, and it is its own matching sum. So one total near w has only one power sum about w."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23f"]=(C["23f"]||[]).concat([{"q": "f is smooth at w. Must its matching sum at w rebuild f near w?", "a": "no: e^(−1/x²), with the value 0 at 0, is smooth, and its matching sum at 0 is 0", "w": ["yes, inside the reach of the sum", "no: a smooth f never equals its matching sum", "yes: smooth means it has every match"], "why": "Flat-point technique: every slope of that function at 0 is 0, yet the function is positive away from 0."}, {"q": "f and g are smooth and have all the same slopes at 0. Must they agree near 0?", "a": "no: add e^(−1/x²) to f, and every slope at 0 stays the same", "w": ["yes, by the match technique", "yes, by the smooth-sum technique", "no: they then differ at 0 too"], "why": "The slopes at one point fix the matching sum. They do not fix the function."}, {"q": "To find the slopes of e^(−1/x²) at 0, may you put ∞ in: Pₙ(∞) · e^(−∞)?", "a": "no: ∞ is not a number to put in; the limit needs f(x)/xᵐ → 0", "w": ["no: the slopes at 0 do not exist", "yes: e^(−∞) = 0", "yes: anything times 0 is 0"], "why": "A polynomial in 1/x grows as x nears 0 while e^(−1/x²) shrinks. Which wins has to be proved: powers lose to exponentials."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23g"]=(C["23g"]||[]).concat([{"q": "x is a whole number and x > 0. Does x ≥ 1 follow?", "a": "yes: that is the step both proofs turn on", "w": ["only if x is even", "no: only x ≥ 0 follows", "no: x could be ½"], "why": "Each proof builds a whole number that lies strictly between 0 and 1, and there is none."}, {"q": "π does not repeat in its first 10 million digits. Is it thereby shown to be no fraction?", "a": "no: checking digits proves nothing about the rest; the proof does", "w": ["yes: a fraction would have repeated by then", "no: π is a fraction, 22/7", "yes, with more digits to be sure"], "why": "A fraction may repeat only after more digits than anyone has looked at. The irrationality technique for π covers every p and q at once."}, {"q": "Is √2 algebraic?", "a": "yes: it is a root of x² − 2 = 0", "w": ["no: it is transcendental", "yes: it is a fraction", "no: it is irrational"], "why": "Irrational and transcendental are different words. √2 is no fraction, and still a root of a polynomial with whole coefficients."}, {"q": "a and b are both irrational. Is a + b thereby irrational?", "a": "no: √2 and −√2 are irrational, and their sum is 0", "w": ["yes: a sum of irrationals is irrational", "no: a sum of irrationals is always a fraction", "yes, unless one of them is 0"], "why": "Being no fraction is not kept by adding. Each sum needs its own proof."}, {"q": "e = 2.7183 to four places. Is e = 27183/10⁴?", "a": "no: four places fence e; they do not name it", "w": ["yes, to within rounding, which is the same", "no: e has only three places", "yes"], "why": "No whole numbers p and q make e = p/q. Any number of places gives a fence, and e lies inside without being its edge."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23h"]=(C["23h"]||[]).concat([{"q": "Is e^(−1/x²) = Σ (−1/x²)ᵏ/k! a power sum about 0?", "a": "no: powers of 1/x are not powers of x", "w": ["no: the sum wanders for every x", "yes, by the building technique", "yes, with reach 1"], "why": "The building technique puts cxᵐ in for x. 1/x² is no such thing, and that function is not rebuilt from 0."}, {"q": "A sum for f about w was built from sums you know. Could the matching sum of f about w be a different one?", "a": "no: a function has only one power sum about a point", "w": ["yes: built sums and matching sums differ by the error", "it cannot be told without the slopes of f", "yes, unless f is a polynomial"], "why": "Smooth-sum technique. So a sum built honestly is the matching sum, and no slope needs to be found."}, {"q": "Is (Σ uₖxᵏ)(Σ vₖxᵏ) = Σ uₖvₖxᵏ?", "a": "no: the piece with xᵏ gathers every pair of powers that adds to k", "w": ["no: the product is no power sum", "yes: multiply piece by piece", "yes, inside both reaches"], "why": "Product technique: the number in front of xᵏ is u₀vₖ + u₁vₖ₋₁ + ⋯ + uₖv₀."}, {"q": "Is the number in front of xᵏ in (1 + x)^α equal to αᵏ/k!?", "a": "no: that is the sum for e^(αx); α choose k is α(α − 1)⋯(α − k + 1)/k!", "w": ["yes", "no: it is αᵏ", "no: it is α/k!"], "why": "Each slope of (1 + x)^α brings down the power and lowers it by 1."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23i"]=(C["23i"]||[]).concat([{"q": "A total has the fence [0.1234564, 0.1234566], narrower than 0.0000005. Are six places known?", "a": "no: the fence holds 0.1234565, the boundary halfway between two roundings", "w": ["yes: 0.123457", "no: a fence must be narrower than 0.00000005", "yes: 0.123456"], "why": "Rounding-fence technique: every number in the fence must round to the same places. A narrow fence is needed, and it is not enough."}, {"q": "Before adding pieces of the sum for sin at an angle of 10 radians, what does the bring-near technique do?", "a": "takes whole half turns off the angle, by facts that are exact", "w": ["rounds the angle to the nearest whole half turn", "turns the angle into degrees", "adds more pieces to make up for the size"], "why": "Near the centre the pieces shrink fast from the first one. Only the facts used to move the input need more places."}, {"q": "The signs of a sum take turns and its sizes fall. Which fence for the leftover is cheapest?", "a": "the bracket: the leftover is smaller than the next piece", "w": ["the error ceiling, with a ceiling on a slope", "none: add pieces until they stop changing", "a geometric sum: the next piece over 1 − k"], "why": "Cheapest-fence technique. The bracket needs no ratio and no slope."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23j"]=(C["23j"]||[]).concat([{"q": "What is the storing function of a list u₀, u₁, u₂, …?", "a": "the power sum Σ uₖxᵏ, wherever it settles", "w": ["the polynomial through the first n entries", "the function with f(k) = uₖ", "the running totals u₀ + u₁ + ⋯ + uₙ"], "why": "Accepted name: the generating function."}, {"q": "A(0) = B(0). Are the two stored lists the same?", "a": "no: agreeing at 0 fixes only the first entry; they must agree near 0", "w": ["yes, by the read-back technique", "no: two lists never have storing functions that agree at 0", "yes, if both reaches are above 0"], "why": "Read-back technique: two lists whose storing functions agree near 0 are the same list."}, {"q": "A storing function A has reach above 0. How does it give back its list?", "a": "uₖ = A⁽ᵏ⁾(0)/k!", "w": ["uₖ = A(k)", "uₖ = A⁽ᵏ⁾(0)", "uₖ = A(1/k)"], "why": "Read-back technique: the smooth-sum technique, used as a filing system."}, {"q": "Which number stands in front of xⁿ in A(x)B(x)?", "a": "u₀vₙ + u₁vₙ₋₁ + ⋯ + uₙv₀", "w": ["u₀v₀ + u₁v₁ + ⋯ + uₙvₙ", "uₙ + vₙ", "uₙvₙ"], "why": "It collects every way to split n into a part from A and a part from B."}, {"q": "The storing function of the rabbit counts is x/(1 − x − x²), which is −1 at x = 1. Is 0 + 1 + 1 + 2 + 3 + ⋯ = −1?", "a": "no: 1 lies outside the reach, and there the sum wanders", "w": ["no: the total is 1", "yes: the function stores the list", "yes, by the read-back technique"], "why": "The function equals the power sum only inside the reach, which is less than 1 here."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23k"]=(C["23k"]||[]).concat([{"q": "1 − x + 2!x² − 3!x³ + ⋯ wanders for every x other than 0. Does it then say nothing about the function it came from?", "a": "no: stopped early it computes; at x = 0.1, nine pieces give the function to within 0.0004", "w": ["no: it settles after all, by taking turns", "yes: a sum that wanders has no use", "yes, except at x = 0"], "why": "Each error is at most the next piece in size. While the pieces are still small, so is the error."}, {"q": "n! ~ √(2πn)(n/e)ⁿ. Does n! − √(2πn)(n/e)ⁿ head to 0?", "a": "no: ~ speaks of the ratio; the difference grows", "w": ["yes, by the trapezoid-fence technique", "no: the ratio does not head to 1 either", "yes: that is what ~ says"], "why": "The ratio heads to 1, while both sides grow past every ceiling, and so does their difference."}, {"q": "Do more pieces of such an expansion always do better?", "a": "no: the pieces shrink and then grow; stop just before the smallest piece", "w": ["yes: each piece is a correction", "yes, once the signs take turns", "no: only the first piece is of use"], "why": "Cut-at-the-smallest technique. Past the smallest piece the bound gets worse with every piece added."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
(function(C){C["23l"]=(C["23l"]||[]).concat([{"q": "Which are the weights of the parabola sum on a pair of strips?", "a": "h/3, 4h/3, h/3", "w": ["h/2, h, h/2", "h/4, h/2, h/4", "h, h, h"], "why": "Sₕ = (h/3)(f₀ + 4f₁ + 2f₂ + 4f₃ + ⋯ + 4f_{N−1} + f_N)."}, {"q": "Does the h² bound of the trapezoid technique hold for √x on [0, 1]?", "a": "no: its second slope has no ceiling near 0", "w": ["yes, with K = 1", "yes: √x is continuous on [0, 1]", "no: √x has no area on [0, 1]"], "why": "The technique asks for |f″| ≤ K on the whole of [u, v]. There the error shrinks more slowly than h²."}, {"q": "Is the parabola sum exact for t⁴?", "a": "no: ∫ t⁴ over [−1, 1] is 2/5, and the technique with h = 1 gives 2/3", "w": ["yes: it is exact up to degree 4", "yes: it is exact for every polynomial", "no: it is exact only up to degree 2"], "why": "It is exact for every polynomial of degree 3 or less. The error bound has the fourth slope in it."}, {"q": "On [−1, 1], how many heights does the best-points technique use to be exact for every polynomial of degree 3 or less?", "a": "two", "w": ["one", "four", "three"], "why": "f(−1/√3) + f(1/√3). Two well-placed heights do the work of the parabola technique’s three."}]);})(window.LADDER_CARDS=window.LADDER_CARDS||{});
